SELECT p.pid,t.tid,t.name,s.ts,s.dur,s.state,s.cpu,s.blocked_function FROM thread_state s JOIN thread t USING(utid) LEFT JOIN process p USING(upid) WHERE (p.pid=12989 OR p.pid IN (SELECT DISTINCT p.pid FROM slice s JOIN thread_track tt ON s.track_id=tt.id JOIN thread t USING(utid) JOIN process p USING(upid) WHERE s.name='client-seek') OR t.tid IN (12989,12993,12994,12995,12996,12997,12998,12999,13000,13001,13002,13004,13006,13007,13008,13052,13053,13057,13058,13059,13060,13064,13065,13066,13067,13068,13070,13071,13072,13073,13074,13076,13082,13083,13086,13087,13089,13127,13155,13156,13162,13163,13164,13165,13168,13178,13181,13184,13188,13189,13507,13514,13526,13529,13536,13544,13662,13663,13665,14574,14575,14580,14582,14584,22294,22588,22768,23507,23517,23615,23616,23634,23636,23637,23785,23786,23787,23827,23828,23829,23830,23831,23832,23833,23834,23835,23916,23919,23920)) AND s.dur>0 ORDER BY s.ts;
